nt, bt = 8000, 1840
nc, bc = 2000, 420
cost, value, margin = 5000, 60, 0.35
pt, pc = bt / nt, bc / nc
se = (pt * (1 - pt) / nt + pc * (1 - pc) / nc) ** 0.5
u = pt - pc
roi = {}
for name, x in (('central', u), ('pessimistic', u - 1.96 * se), ('optimistic', u + 1.96 * se)):
    roi[name] = (x * nt * value * margin - cost) / cost
    print(name + ':', round(roi[name], 2))
if roi['pessimistic'] > 0:
    print('decision: scale')
elif roi['central'] > 0:
    print('decision: repeat test')
else:
    print('decision: stop')
